package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// OrderRec corresponds to FD ORDER-FILE 01 ORDER-REC
type OrderRec struct {
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

// additional globals for file handling and current record
var orderFileLines []string
var orderFileIdx int
var currOrder OrderRec

func truncateHighOrder(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	sign := v.Sign()
	abs := v
	if sign < 0 {
		abs = v.Neg()
	}
	// integer and fractional parts of abs
	intPart := abs.Truncate(0)
	fracPart := abs.Sub(intPart)
	intStr := intPart.StringFixed(0)
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	var fracStr string
	if scale > 0 {
		shifted := fracPart.Shift(int32(scale)).Truncate(0)
		fracStr = shifted.StringFixed(0)
		if len(fracStr) < scale {
			fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
		} else if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
	}
	var recon string
	if scale > 0 {
		recon = intStr + "." + fracStr
	} else {
		recon = intStr
	}
	dec, err := decimal.NewFromString(recon)
	if err != nil {
		dec = decimal.NewFromInt(0)
	}
	if sign < 0 {
		dec = dec.Neg()
	}
	return dec
}

func setWsTotal(raw decimal.Decimal, rounded bool) {
	var v decimal.Decimal
	if rounded {
		v = raw.Round(2)
	} else {
		v = raw.Truncate(2)
	}
	WsTotal = truncateHighOrder(v, 8, 2)
}

func addToGrand(delta decimal.Decimal) {
	sum := WsGrand.Add(delta)
	v := sum.Truncate(2)
	WsGrand = truncateHighOrder(v, 10, 2)
}

func incCount(cnt *int64, digits int) {
	base := int64(1)
	for i := 0; i < digits; i++ {
		base *= 10
	}
	*cnt = (*cnt + 1) % base
	if *cnt < 0 {
		*cnt += base
	}
}

func formatPIC99(cnt int64) string {
	// cnt already modulo 100
	if cnt < 0 {
		cnt = (cnt%100 + 100) % 100
	} else {
		cnt = cnt % 100
	}
	return fmt.Sprintf("%02d", cnt)
}

func formatEdited(v decimal.Decimal, picture string) string {
	abs := v.Abs()
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	var fracLen int
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		fracLen = len(fracPic)
	} else {
		intPic = picture
		fracLen = 0
	}
	// count placeholders in intPic
	phCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			phCount++
		}
	}
	intPart := abs.Truncate(0)
	intStr := intPart.StringFixed(0)
	if len(intStr) > phCount {
		intStr = intStr[len(intStr)-phCount:]
	} else if len(intStr) < phCount {
		intStr = strings.Repeat("0", phCount-len(intStr)) + intStr
	}
	// build output for integer part
	out := make([]rune, len(intPic))
	dIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			out[i] = rune(intStr[dIdx])
			dIdx++
		} else if ch == ',' {
			out[i] = ','
		} else {
			out[i] = ch
		}
	}
	// suppression
	suppressing := true
	for i, chPic := range intPic {
		if chPic == 'Z' {
			if suppressing && out[i] == '0' {
				out[i] = ' '
			} else {
				suppressing = false
			}
		} else if chPic == '9' {
			suppressing = false
		} else if chPic == ',' {
			if suppressing {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	intFormatted := string(out)
	if fracLen > 0 {
		fracPart := abs.Sub(abs.Truncate(0))
		shifted := fracPart.Shift(int32(fracLen)).Truncate(0)
		fracStr := shifted.StringFixed(0)
		if len(fracStr) < fracLen {
			fracStr = strings.Repeat("0", fracLen-len(fracStr)) + fracStr
		} else if len(fracStr) > fracLen {
			fracStr = fracStr[len(fracStr)-fracLen:]
		}
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

// paragraphs

func ReadPara() {
	if orderFileIdx >= len(orderFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderFileLines[orderFileIdx]
	orderFileIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	orId := line[0:5]
	orStat := line[5:6]
	orQtyStr := line[6:9]
	orPriceStr := line[9:15]

	var qty int64
	qs := strings.TrimSpace(orQtyStr)
	if qs != "" {
		qsClean := strings.ReplaceAll(qs, " ", "")
		if qsClean != "" {
			if v, err := strconv.ParseInt(qsClean, 10, 64); err == nil {
				qty = v
			}
		}
	}
	var price decimal.Decimal
	ps := strings.TrimSpace(orPriceStr)
	if ps == "" {
		price = decimal.NewFromInt(0)
	} else {
		psClean := strings.ReplaceAll(ps, " ", "")
		if v, err := strconv.ParseInt(psClean, 10, 64); err == nil {
			price = decimal.New(v, -2)
		} else {
			price = decimal.NewFromInt(0)
		}
	}
	currOrder = OrderRec{
		OrId:    orId,
		OrStat:  orStat,
		OrQty:   qty,
		OrPrice: price,
	}
}

func ShowPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(currOrder.OrQty), "ZZ9")
	WsPriceEd = formatEdited(currOrder.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", currOrder.OrId, currOrder.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func ProcessPara() {
	// MOVE 0 TO WS-TOTAL
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if currOrder.OrQty == 0 {
		incCount(&WsBadQty, 2)
		fmt.Printf("%s BAD QTY\n", currOrder.OrId)
	} else if currOrder.OrStat == "N" {
		qtyDec := decimal.NewFromInt(currOrder.OrQty)
		raw := qtyDec.Mul(currOrder.OrPrice)
		setWsTotal(raw, false)
		incCount(&WsNewCount, 2)
		ShowPara()
	} else if currOrder.OrStat == "S" {
		qtyDec := decimal.NewFromInt(currOrder.OrQty)
		raw := qtyDec.Mul(currOrder.OrPrice).Mul(decimal.RequireFromString("1.05"))
		setWsTotal(raw, true)
		incCount(&WsShipCount, 2)
		ShowPara()
	} else if currOrder.OrStat == "C" {
		incCount(&WsCancelCount, 2)
		ShowPara()
	} else {
		incCount(&WsInvalid, 2)
		fmt.Printf("%s BAD STATUS %s\n", currOrder.OrId, currOrder.OrStat)
	}
	addToGrand(WsTotal)
	ReadPara()
}

func SummaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatPIC99(WsNewCount), formatPIC99(WsShipCount), formatPIC99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatPIC99(WsInvalid), formatPIC99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	var lines []string
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
			os.Exit(1)
		}
		lines = []string{}
	} else {
		if len(data) == 0 {
			lines = []string{}
		} else {
			txt := string(data)
			txt = strings.ReplaceAll(txt, "\r\n", "\n")
			txt = strings.ReplaceAll(txt, "\r", "\n")
			lines = strings.Split(txt, "\n")
			if len(lines) > 0 && lines[len(lines)-1] == "" {
				lines = lines[:len(lines)-1]
			}
		}
	}
	orderFileLines = lines
	orderFileIdx = 0
	WsEofFlag = "N"
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
